import {mkdtempSync,rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {spawnSync} from 'node:child_process';
import {sourceFingerprint} from './scripts/documentation-lib.mjs';
const temporary=mkdtempSync(join(tmpdir(),'lorcana-git-checkout-'));
try {
 const archive=spawnSync('git',['archive','d01f76cd7d987287d6da74d27ac9ce0349b2c318'],{maxBuffer:16*1024*1024});
 if(archive.status!==0)throw new Error('Git archive failed');
 const unpack=spawnSync('tar',['-xf','-','-C',temporary],{input:archive.stdout});
 if(unpack.status!==0)throw new Error('Archive extraction failed');
 if(sourceFingerprint(temporary)!==sourceFingerprint(process.cwd()))throw new Error('Canonical Git source fingerprint differs');
 const environment={...process.env};
 for(const key of Object.keys(environment))if(/^(?:PG|POSTGRES|DATABASE_|BOOTSTRAP_)|SECRET|PASSWORD|TOKEN|PRIVATE_KEY/.test(key))delete environment[key];
 for(const args of [['install','--frozen-lockfile'],['verify:foundation']]) {
  const result=spawnSync('pnpm',args,{cwd:temporary,env:environment,stdio:'inherit'});
  if(result.status!==0)throw new Error('Canonical Git checkout check failed: '+args.join(' '));
 }
 console.log('PASS canonical Git checkout frozen install and full43-test foundation; source fingerprint equals final live source; no credentials/database copied');
} finally {rmSync(temporary,{recursive:true,force:true});}
